from collections import deque, Counter

def comps_same_color(grid,bg, rlim=(0,13)):
    H=len(grid); W=len(grid[0]); seen=set(); comps=[]
    for r in range(rlim[0],rlim[1]):
      for c in range(W):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          rr,cc=q.pop(); cells.append((rr,cc))
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=rr+dr,cc+dc
            if rlim[0]<=nr<rlim[1] and 0<=nc<W and (nr,nc) not in seen and grid[nr][nc]==col:
              seen.add((nr,nc));q.append((nr,nc))
        comps.append((col,cells))
    return comps

def project_grid(inp,bg,panels,top_end):
    out=[row.copy() for row in inp]
    comps=comps_same_color(inp,bg,(0,top_end))
    # remove top non-bg objects
    for r in range(top_end):
      for c in range(len(inp[0])):
        if inp[r][c]!=bg: out[r][c]=bg
    # map each same-color connected component if its color matches panel fill
    for col,cells in comps:
      rs=[r for r,c in cells]; cs=[c for r,c in cells]
      rmin,rmax=min(rs),max(rs); cmin,cmax=min(cs),max(cs)
      for top,bottom,fill,edge in panels:
        if col!=fill: continue
        dest_bottom=bottom
        shift=dest_bottom-rmax
        for r,c in cells:
          rr=r+shift
          if top<=rr<=bottom:
            out[rr][c]=edge
    return out

